PRODUCTION_SOURCE = '"""\nOLA-042\nOracle Persisted Cohort Staging Router\n\nCanonical production integration boundary around the existing PostgreSQL\ncanonical observation persistence router.\n\nPurpose:\n- delegate canonical observation routing to the existing persistence router\n- preserve the exact CanonicalObservation objects presented to route_batch\n- stage the exact cohort only after successful delegated atomic batch routing\n- key staged cohorts by acquisition_batch_id\n- never promote staged cohorts into OLA-040 capture by itself\n- allow later OLA-017 completion reconciliation to promote the exact staged\n  cohort through OLA-041\n\nThis boundary does not own PostgreSQL persistence semantics.\nIt does not weaken OLA-015 routing.\nIt does not perform lineage advancement.\nIt does not interpret intelligence, score signals, alert, hand off to Q Series,\nauthorize trading, place orders, move funds, or mutate portfolios.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nimport json\nfrom threading import RLock\nfrom types import MappingProxyType\nfrom typing import Any, Mapping, Sequence\n\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n)\n\n\nSCHEMA_VERSION = "OLA-042"\nENGINE_ID = "OLA-042"\nSTAGE_TYPE = "oracle_persisted_canonical_cohort_stage"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass PersistedCohortStagingRouterContractError(ValueError):\n    """Raised when OLA-042 staging input is malformed."""\n\n\nclass PersistedCohortStagingRouterInvariantError(RuntimeError):\n    """Raised when permanent OLA-042 invariants are violated."""\n\n\ndef _require_non_empty_string(\n    value: Any,\n    field_name: str,\n) -> str:\n    if not isinstance(value, str):\n        raise PersistedCohortStagingRouterContractError(\n            f"{field_name} must be a string"\n        )\n\n    normalized = value.strip()\n\n    if not normalized:\n        raise PersistedCohortStagingRouterContractError(\n            f"{field_name} must not be empty"\n        )\n\n    return normalized\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PersistedCanonicalCohortStage:\n    schema_version: str\n    engine_id: str\n    stage_type: str\n    acquisition_batch_id: str\n    canonical_count: int\n    canonical_observations: tuple[CanonicalObservation, ...]\n    observation_ids: tuple[str, ...]\n    source_market_ids: tuple[str, ...]\n    delegated_routing_evidence: tuple[ObservationRoutingEvidence, ...]\n    routing_evidence_observation_ids: tuple[str, ...]\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    stage_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise PersistedCohortStagingRouterInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise PersistedCohortStagingRouterInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.stage_type != STAGE_TYPE:\n            raise PersistedCohortStagingRouterInvariantError(\n                "stage type invariant violated"\n            )\n\n        if self.canonical_count <= 0:\n            raise PersistedCohortStagingRouterInvariantError(\n                "canonical count must be positive"\n            )\n\n        if self.canonical_count != len(\n            self.canonical_observations\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "canonical observation count invariant violated"\n            )\n\n        if self.canonical_count != len(\n            self.delegated_routing_evidence\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "routing evidence count invariant violated"\n            )\n\n        if self.observation_ids != tuple(\n            observation.observation_id\n            for observation in self.canonical_observations\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "observation ordering invariant violated"\n            )\n\n        if (\n            self.routing_evidence_observation_ids\n            != self.observation_ids\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "routing evidence identity ordering invariant violated"\n            )\n\n        if len(set(self.observation_ids)) != self.canonical_count:\n            raise PersistedCohortStagingRouterInvariantError(\n                "observation identity uniqueness invariant violated"\n            )\n\n        if len(set(self.source_market_ids)) != self.canonical_count:\n            raise PersistedCohortStagingRouterInvariantError(\n                "market identity uniqueness invariant violated"\n            )\n\n        if any(\n            evidence.accepted is not True\n            for evidence in self.delegated_routing_evidence\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "staged cohort contains rejected routing evidence"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise PersistedCohortStagingRouterInvariantError(\n                "OLA-042 read-only authority invariants violated"\n            )\n\n    def to_canonical_metadata(\n        self,\n    ) -> Mapping[str, Any]:\n        return MappingProxyType(\n            {\n                "schema_version": self.schema_version,\n                "engine_id": self.engine_id,\n                "stage_type": self.stage_type,\n                "acquisition_batch_id": self.acquisition_batch_id,\n                "canonical_count": self.canonical_count,\n                "observation_ids": self.observation_ids,\n                "source_market_ids": self.source_market_ids,\n                "routing_evidence_observation_ids": (\n                    self.routing_evidence_observation_ids\n                ),\n                "read_only": self.read_only,\n                "execution_allowed": self.execution_allowed,\n                "execution_adapter_resolved": (\n                    self.execution_adapter_resolved\n                ),\n                "execution_adapter_invoked": (\n                    self.execution_adapter_invoked\n                ),\n                "trade_authorization_allowed": (\n                    self.trade_authorization_allowed\n                ),\n                "order_placement_allowed": (\n                    self.order_placement_allowed\n                ),\n                "funds_moved": self.funds_moved,\n                "portfolio_mutated": self.portfolio_mutated,\n                "stage_hash": self.stage_hash,\n            }\n        )\n\n\nclass OraclePersistedCohortStagingRouter:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        persistence_router: Any,\n    ) -> None:\n        route_batch = getattr(\n            persistence_router,\n            "route_batch",\n            None,\n        )\n\n        if not callable(route_batch):\n            raise PersistedCohortStagingRouterContractError(\n                "persistence_router must expose callable route_batch"\n            )\n\n        self._persistence_router = persistence_router\n        self._lock = RLock()\n        self._pending: dict[\n            str,\n            PersistedCanonicalCohortStage,\n        ] = {}\n        self._consumed_batch_ids: set[str] = set()\n\n    @property\n    def persistence_router(self) -> Any:\n        return self._persistence_router\n\n    def __call__(\n        self,\n        observation: CanonicalObservation,\n        routed_at: Any,\n    ) -> ObservationRoutingEvidence:\n        route = getattr(\n            self._persistence_router,\n            "__call__",\n            None,\n        )\n\n        if not callable(route):\n            raise PersistedCohortStagingRouterContractError(\n                "persistence_router must remain callable"\n            )\n\n        return route(\n            observation,\n            routed_at,\n        )\n\n    def route_batch(\n        self,\n        observations: Sequence[CanonicalObservation],\n        routed_at: Any,\n    ) -> tuple[ObservationRoutingEvidence, ...]:\n        canonical_observations = tuple(observations)\n\n        if not canonical_observations:\n            raise PersistedCohortStagingRouterContractError(\n                "route_batch observations must not be empty"\n            )\n\n        batch_ids: set[str] = set()\n        observation_ids: list[str] = []\n        observation_id_set: set[str] = set()\n        source_market_ids: list[str] = []\n        source_market_id_set: set[str] = set()\n\n        for observation in canonical_observations:\n            if not isinstance(\n                observation,\n                CanonicalObservation,\n            ):\n                raise PersistedCohortStagingRouterContractError(\n                    "route_batch requires CanonicalObservation records"\n                )\n\n            if observation.observation_type != "market_snapshot":\n                raise PersistedCohortStagingRouterContractError(\n                    "OLA-042 accepts only market_snapshot observations"\n                )\n\n            batch_id = _require_non_empty_string(\n                observation.acquisition_batch_id,\n                "observation.acquisition_batch_id",\n            )\n            observation_id = _require_non_empty_string(\n                observation.observation_id,\n                "observation.observation_id",\n            )\n\n            payload = dict(observation.payload)\n            source_market_id = _require_non_empty_string(\n                payload.get("source_market_id"),\n                "observation.payload.source_market_id",\n            )\n\n            if observation_id in observation_id_set:\n                raise PersistedCohortStagingRouterContractError(\n                    "duplicate observation_id within batch"\n                )\n\n            if source_market_id in source_market_id_set:\n                raise PersistedCohortStagingRouterContractError(\n                    "duplicate source_market_id within batch"\n                )\n\n            batch_ids.add(batch_id)\n            observation_id_set.add(observation_id)\n            observation_ids.append(observation_id)\n            source_market_id_set.add(source_market_id)\n            source_market_ids.append(source_market_id)\n\n        if len(batch_ids) != 1:\n            raise PersistedCohortStagingRouterContractError(\n                "batch must share one acquisition_batch_id"\n            )\n\n        acquisition_batch_id = next(iter(batch_ids))\n\n        with self._lock:\n            if acquisition_batch_id in self._pending:\n                raise PersistedCohortStagingRouterContractError(\n                    "acquisition batch already staged"\n                )\n\n            if acquisition_batch_id in self._consumed_batch_ids:\n                raise PersistedCohortStagingRouterContractError(\n                    "consumed acquisition batch cannot be restaged"\n                )\n\n        delegated = self._persistence_router.route_batch(\n            canonical_observations,\n            routed_at,\n        )\n\n        if not isinstance(delegated, tuple):\n            try:\n                delegated = tuple(delegated)\n            except TypeError as exc:\n                raise PersistedCohortStagingRouterInvariantError(\n                    "delegated route_batch returned non-iterable evidence"\n                ) from exc\n\n        if len(delegated) != len(canonical_observations):\n            raise PersistedCohortStagingRouterInvariantError(\n                "delegated routing evidence count mismatch"\n            )\n\n        evidence_by_observation_id: dict[\n            str,\n            ObservationRoutingEvidence,\n        ] = {}\n\n        for evidence in delegated:\n            if not isinstance(\n                evidence,\n                ObservationRoutingEvidence,\n            ):\n                raise PersistedCohortStagingRouterInvariantError(\n                    "delegated route_batch returned incompatible evidence"\n                )\n\n            if evidence.accepted is not True:\n                raise PersistedCohortStagingRouterInvariantError(\n                    "delegated route_batch returned rejected evidence"\n                )\n\n            if evidence.observation_id in evidence_by_observation_id:\n                raise PersistedCohortStagingRouterInvariantError(\n                    "duplicate delegated routing evidence identity"\n                )\n\n            evidence_by_observation_id[\n                evidence.observation_id\n            ] = evidence\n\n        if set(evidence_by_observation_id) != set(observation_ids):\n            raise PersistedCohortStagingRouterInvariantError(\n                "delegated routing evidence identity set mismatch"\n            )\n\n        ordered_evidence = tuple(\n            evidence_by_observation_id[observation_id]\n            for observation_id in observation_ids\n        )\n\n        metadata_payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "stage_type": STAGE_TYPE,\n            "acquisition_batch_id": acquisition_batch_id,\n            "canonical_count": len(canonical_observations),\n            "observation_ids": observation_ids,\n            "source_market_ids": source_market_ids,\n            "content_hashes": [\n                observation.content_hash\n                for observation in canonical_observations\n            ],\n            "replay_hashes": [\n                observation.replay_hash\n                for observation in canonical_observations\n            ],\n            "routing_evidence_observation_ids": [\n                evidence.observation_id\n                for evidence in ordered_evidence\n            ],\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        stage = PersistedCanonicalCohortStage(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            stage_type=STAGE_TYPE,\n            acquisition_batch_id=acquisition_batch_id,\n            canonical_count=len(canonical_observations),\n            canonical_observations=canonical_observations,\n            observation_ids=tuple(observation_ids),\n            source_market_ids=tuple(source_market_ids),\n            delegated_routing_evidence=ordered_evidence,\n            routing_evidence_observation_ids=tuple(\n                evidence.observation_id\n                for evidence in ordered_evidence\n            ),\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n            stage_hash=_stable_hash(metadata_payload),\n        )\n\n        stage.assert_invariants()\n\n        with self._lock:\n            if acquisition_batch_id in self._pending:\n                raise PersistedCohortStagingRouterInvariantError(\n                    "staging race detected for acquisition batch"\n                )\n\n            self._pending[acquisition_batch_id] = stage\n\n        return ordered_evidence\n\n    def consume_stage(\n        self,\n        *,\n        acquisition_batch_id: str,\n    ) -> PersistedCanonicalCohortStage:\n        batch_id = _require_non_empty_string(\n            acquisition_batch_id,\n            "acquisition_batch_id",\n        )\n\n        with self._lock:\n            if batch_id in self._consumed_batch_ids:\n                raise PersistedCohortStagingRouterContractError(\n                    "acquisition batch stage already consumed"\n                )\n\n            stage = self._pending.pop(\n                batch_id,\n                None,\n            )\n\n            if stage is None:\n                raise PersistedCohortStagingRouterContractError(\n                    "no pending persisted cohort stage for batch"\n                )\n\n            stage.assert_invariants()\n            self._consumed_batch_ids.add(batch_id)\n\n        return stage\n\n    def peek_stage_metadata(\n        self,\n        *,\n        acquisition_batch_id: str,\n    ) -> Mapping[str, Any] | None:\n        batch_id = _require_non_empty_string(\n            acquisition_batch_id,\n            "acquisition_batch_id",\n        )\n\n        with self._lock:\n            stage = self._pending.get(batch_id)\n\n            if stage is None:\n                return None\n\n            return stage.to_canonical_metadata()\n\n    @property\n    def pending_stage_count(self) -> int:\n        with self._lock:\n            return len(self._pending)\n\n    @property\n    def consumed_stage_count(self) -> int:\n        with self._lock:\n            return len(self._consumed_batch_ids)\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_persisted_cohort_staging_router import (\n    OraclePersistedCohortStagingRouter,\n    PersistedCohortStagingRouterContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    16,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id="batch.ola.042.1",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": "0.6140",\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    batch_id="batch.ola.042.1",\n):\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-STAGE-{index}",\n            frame_id=str(index),\n            batch_id=batch_id,\n        )\n        for index in range(1, 6)\n    )\n\n\nclass FakePersistenceRouter:\n    def __init__(\n        self,\n        *,\n        fail_batch=False,\n    ):\n        self.fail_batch = fail_batch\n        self.batch_calls = 0\n        self.single_calls = 0\n        self.last_observations = None\n        self.last_routed_at = None\n\n    def __call__(\n        self,\n        observation,\n        routed_at,\n    ):\n        self.single_calls += 1\n\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.persistence.single",\n            metadata={\n                "test": "OLA-042",\n            },\n        )\n\n    def route_batch(\n        self,\n        observations,\n        routed_at,\n    ):\n        self.batch_calls += 1\n        self.last_observations = tuple(observations)\n        self.last_routed_at = routed_at\n\n        if self.fail_batch:\n            raise RuntimeError(\n                "delegated persistence failed"\n            )\n\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.persistence.batch",\n                metadata={\n                    "test": "OLA-042",\n                },\n            )\n            for observation in observations\n        )\n\n\ndef run_successful_stage_test():\n    persistence_router = FakePersistenceRouter()\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=persistence_router\n    )\n    cohort = build_cohort()\n\n    evidence = router.route_batch(\n        cohort,\n        T1,\n    )\n\n    assert persistence_router.batch_calls == 1\n    assert persistence_router.last_observations == cohort\n    assert all(\n        delegated is original\n        for delegated, original in zip(\n            persistence_router.last_observations,\n            cohort,\n        )\n    )\n    assert len(evidence) == 5\n    assert router.pending_stage_count == 1\n    assert router.consumed_stage_count == 0\n\n    stage = router.consume_stage(\n        acquisition_batch_id="batch.ola.042.1"\n    )\n\n    assert stage.schema_version == "OLA-042"\n    assert stage.engine_id == "OLA-042"\n    assert stage.canonical_count == 5\n    assert stage.canonical_observations == cohort\n    assert all(\n        staged is original\n        for staged, original in zip(\n            stage.canonical_observations,\n            cohort,\n        )\n    )\n    assert stage.routing_evidence_observation_ids == (\n        stage.observation_ids\n    )\n    assert router.pending_stage_count == 0\n    assert router.consumed_stage_count == 1\n\n    return router, stage\n\n\ndef run_delegated_failure_never_stages_test():\n    persistence_router = FakePersistenceRouter(\n        fail_batch=True\n    )\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=persistence_router\n    )\n\n    try:\n        router.route_batch(\n            build_cohort(),\n            T1,\n        )\n        raise AssertionError(\n            "delegated persistence failure must propagate"\n        )\n    except RuntimeError:\n        pass\n\n    assert persistence_router.batch_calls == 1\n    assert router.pending_stage_count == 0\n    assert router.consumed_stage_count == 0\n\n\ndef run_duplicate_stage_fail_closed_test():\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n    cohort = build_cohort()\n\n    router.route_batch(\n        cohort,\n        T1,\n    )\n\n    try:\n        router.route_batch(\n            cohort,\n            T1,\n        )\n        raise AssertionError(\n            "duplicate acquisition batch stage must fail closed"\n        )\n    except PersistedCohortStagingRouterContractError:\n        pass\n\n    assert router.pending_stage_count == 1\n\n\ndef run_consumed_stage_restaging_fail_closed_test():\n    router, stage = run_successful_stage_test()\n\n    try:\n        router.route_batch(\n            stage.canonical_observations,\n            T1,\n        )\n        raise AssertionError(\n            "consumed acquisition batch cannot be restaged"\n        )\n    except PersistedCohortStagingRouterContractError:\n        pass\n\n    assert router.pending_stage_count == 0\n    assert router.consumed_stage_count == 1\n\n\ndef run_single_route_delegation_test():\n    persistence_router = FakePersistenceRouter()\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=persistence_router\n    )\n    observation = build_cohort()[0]\n\n    evidence = router(\n        observation,\n        T1,\n    )\n\n    assert evidence.accepted is True\n    assert evidence.observation_id == observation.observation_id\n    assert persistence_router.single_calls == 1\n    assert router.pending_stage_count == 0\n\n\ndef run_mixed_batch_fail_closed_test():\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n    cohort = list(build_cohort())\n\n    cohort[-1] = build_observation(\n        market_id="KXTEST-STAGE-5",\n        frame_id="mixed",\n        batch_id="batch.ola.042.other",\n    )\n\n    try:\n        router.route_batch(\n            cohort,\n            T1,\n        )\n        raise AssertionError(\n            "mixed acquisition batch must fail closed"\n        )\n    except PersistedCohortStagingRouterContractError:\n        pass\n\n    assert router.persistence_router.batch_calls == 0\n    assert router.pending_stage_count == 0\n\n\ndef run_duplicate_market_fail_closed_test():\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n    cohort = list(build_cohort())\n\n    cohort[-1] = build_observation(\n        market_id="KXTEST-STAGE-4",\n        frame_id="duplicate-market",\n    )\n\n    try:\n        router.route_batch(\n            cohort,\n            T1,\n        )\n        raise AssertionError(\n            "duplicate market identity must fail closed"\n        )\n    except PersistedCohortStagingRouterContractError:\n        pass\n\n    assert router.persistence_router.batch_calls == 0\n    assert router.pending_stage_count == 0\n\n\ndef run_peek_metadata_test():\n    router = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n\n    router.route_batch(\n        build_cohort(),\n        T1,\n    )\n\n    metadata = router.peek_stage_metadata(\n        acquisition_batch_id="batch.ola.042.1"\n    )\n\n    assert metadata is not None\n    assert metadata["schema_version"] == "OLA-042"\n    assert metadata["canonical_count"] == 5\n    assert "canonical_observations" not in metadata\n    assert "delegated_routing_evidence" not in metadata\n\n    try:\n        metadata["canonical_count"] = 99\n        raise AssertionError(\n            "stage metadata must be immutable"\n        )\n    except TypeError:\n        pass\n\n\ndef run_deterministic_stage_hash_test():\n    first = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n    second = OraclePersistedCohortStagingRouter(\n        persistence_router=FakePersistenceRouter()\n    )\n\n    first.route_batch(\n        build_cohort(),\n        T1,\n    )\n    second.route_batch(\n        build_cohort(),\n        T1,\n    )\n\n    first_stage = first.consume_stage(\n        acquisition_batch_id="batch.ola.042.1"\n    )\n    second_stage = second.consume_stage(\n        acquisition_batch_id="batch.ola.042.1"\n    )\n\n    assert first_stage == second_stage\n    assert first_stage.stage_hash == second_stage.stage_hash\n\n    return first_stage\n\n\ndef main():\n    _, stage = run_successful_stage_test()\n\n    run_delegated_failure_never_stages_test()\n    run_duplicate_stage_fail_closed_test()\n    run_consumed_stage_restaging_fail_closed_test()\n    run_single_route_delegation_test()\n    run_mixed_batch_fail_closed_test()\n    run_duplicate_market_fail_closed_test()\n    run_peek_metadata_test()\n\n    deterministic = run_deterministic_stage_hash_test()\n\n    result = {\n        "schema_version": stage.schema_version,\n        "engine_id": stage.engine_id,\n        "status": "passed",\n        "existing_persistence_router_delegated": True,\n        "route_batch_delegated_before_stage": True,\n        "delegated_failure_never_stages": True,\n        "exact_canonical_objects_preserved": True,\n        "exact_observation_order_preserved": True,\n        "routing_evidence_identity_reconciled": True,\n        "single_acquisition_batch_identity_enforced": True,\n        "unique_observation_identity_enforced": True,\n        "unique_market_identity_enforced": True,\n        "write_once_stage_per_batch": True,\n        "consume_once_stage_per_batch": True,\n        "consumed_batch_restaging_fails_closed": True,\n        "single_observation_route_delegation_preserved": True,\n        "immutable_metadata_projection": True,\n        "canonical_objects_excluded_from_metadata": True,\n        "deterministic_stage_hash_valid": (\n            deterministic.stage_hash == stage.stage_hash\n        ),\n        "ola_015_persistence_semantics_not_owned": True,\n        "ola_041_promotion_not_owned": True,\n        "no_lineage_advancement_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": stage.read_only,\n        "execution_allowed": stage.execution_allowed,\n        "execution_adapter_resolved": (\n            stage.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            stage.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            stage.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            stage.order_placement_allowed\n        ),\n        "funds_moved": stage.funds_moved,\n        "portfolio_mutated": stage.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-042 Oracle Persisted Cohort "\n        "Staging Router"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-042 INSTALLER")
    print(" ORACLE PERSISTED COHORT STAGING ROUTER")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-042 Oracle Persisted Cohort "
        "Staging Router installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_042_oracle_persisted_"
        "cohort_staging_router.py"
    )


if __name__ == "__main__":
    main()
